  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Tetrabenazine oral systemic availability was very low, mean 0.049 ± 0.032 (4.9%), well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Felodipine median absolute oral bioavailability is 16% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Nitrendipine absolute oral bioavailability was reported as 40% in normal subjects, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules have absolute oral bioavailability below 20%, supporting low; isolated higher nitrendipine reports are outweighed by more condition-matched low values.",
  "evidence_gaps": [
    "Nitrendipine has conflicting absolute bioavailability reports (0.4% to 40%); the more detailed tablet study supports low, but higher values add uncertainty.",
    "Some evidence molecules (delmopinol, batimastat, DMAU) are described only qualitatively as low/poor, without numeric F values.",
    "Several records come from patient populations or altered conditions (e.g., liver cirrhosis, epileptic patients, fed/chronic dosing) that may not reflect ordinary conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

